class Solution:
    def fewestBoats(self, weights: List[int], limit: int) -> int:
        a = sorted(weights, reverse=True)
        taken = [False] * len(a)
        boats = 0
        for i in range(len(a)):
            if taken[i]:
                continue
            taken[i] = True
            boats += 1
            for j in range(i + 1, len(a)):
                if not taken[j] and a[i] + a[j] <= limit:
                    taken[j] = True
                    break
        return boats

