class Solution {
    public int fewestBoats(int[] weights, int limit) {
        int n = weights.length, boats = 0;
        int[] a = weights.clone();
        Arrays.sort(a);
        boolean[] taken = new boolean[n];
        for (int i = n - 1; i >= 0; i--) {
            if (taken[i]) continue;
            taken[i] = true;
            boats++;
            for (int j = i - 1; j >= 0; j--)
                if (!taken[j] && a[i] + a[j] <= limit) { taken[j] = true; break; }
        }
        return boats;
    }
}

