static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int fewestBoats(int* weights, int weightsSize, int limit) {
    int n = weightsSize, boats = 0;
    int* a = malloc(n * sizeof(int));
    memcpy(a, weights, n * sizeof(int));
    qsort(a, n, sizeof(int), cmp_int);
    char* taken = calloc(n, 1);
    for (int i = n - 1; i >= 0; i--) {
        if (taken[i]) continue;
        taken[i] = 1;
        boats++;
        for (int j = i - 1; j >= 0; j--)
            if (!taken[j] && a[i] + a[j] <= limit) { taken[j] = 1; break; }
    }
    free(a); free(taken);
    return boats;
}

