class Solution:
    def fewestBoats(self, weights: List[int], limit: int) -> int:
        a = sorted(weights)
        i, j, boats = 0, len(a) - 1, 0
        while i <= j:
            if a[i] + a[j] <= limit:
                i += 1
            j -= 1
            boats += 1
        return boats

